import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def check_good_set_3(a, b, c):
    # Assumes a, b, c are distinct positive integers

    # Condition 1: GCD = 1
    if gcd3(a, b, c) != 1:
        return False

    # Condition 2: Pairwise divisibility (a|bc, b|ac, c|ab)
    if (b * c) % a != 0:
        return False
    if (a * c) % b != 0:
        return False
    if (a * b) % c != 0:
        return False

    return True

def find_examples(max_val=20):
    examples = []

    # Iterate a < b < c
    for a in range(2, max_val):
        for b in range(a + 1, max_val):
            for c in range(b + 1, max_val):
                if check_good_set_3(a, b, c):
                    m = a * b * c
                    examples.append((m, a, b, c))

    # Sort by product m
    examples.sort(key=lambda x: x[0])
    return examples

# Run the search with a moderate bound
results = find_examples(max_val=25)

print("Found Examples (m, a, b, c):")
for m, a, b, c in results:
    print(f"m={m}, U={{a={a}, b={b}, c={c}}}")

# Count how many we found
print(f"\nTotal examples found within the bound: {len(results)}")

